Fixpoint chain_okF (G : list frame) (m : mem) : Prop :=
  match G with
  | [] => False
  | [f] => fr_fn f = CATCH_FN /\ fr_callsite f = CATCH_CS /\ bv_unsigned (c_sp (fr_live f)) = fr_sp f /\ base_okF (fr_sp f)
  | f :: ((g :: _) as G') =>
         chain_okF G' m
      /\ site_okF (fr_fn f) (fr_callsite f) = true
      /\ bv_unsigned (c_sp (fr_live f)) = fr_sp f
      /\ fr_sp f + fsizeF (fr_fn f) = fr_sp g
      /\ fr_ra f = wz (fr_callsite g + 4)
      /\ saves_okF f (fr_live g) m
      /\ agreesF f (fr_live g)
  end.

